const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),ui={lights:document.querySelector('#lights'),distance:document.querySelector('#distance'),overlay:document.querySelector('#overlay'),title:document.querySelector('#title'),kicker:document.querySelector('#kicker'),message:document.querySelector('#message'),start:document.querySelector('#start'),announcement:document.querySelector('#announcement'),sound:document.querySelector('#sound'),reflection:document.querySelector('#reflection')};
const messages=['REMEMBER THE DATE','HONOR THE LIVES LOST','REMEMBER THE FIRST RESPONDERS','HONOR THE SURVIVORS','REMEMBER THE FAMILIES','COURAGE IN THE FACE OF FEAR','ORDINARY PEOPLE HELPED STRANGERS','UNITY CAN FOLLOW TRAGEDY','CHOOSE COMPASSION OVER HATE','TEACH THE NEXT GENERATION','SEPTEMBER 11, 2001 · NEVER FORGET'];let W=360,H=560,dpr=1,state='ready',last=0,t=0,count=0,distance=0,plane,lights=[],particles=[],audio=true,ac;
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}function spawn(x,y){lights.push({x,y:y??95+Math.random()*(H-245),taken:false,pulse:Math.random()*6})}function reset(){t=count=distance=0;plane={x:W*.25,y:H*.38,vy:-100,rot:0};lights=[];particles=[];for(let i=0;i<5;i++)spawn(W+100+i*W*.52);sync()}
function sync(){ui.lights.textContent=`${count} / 11`;ui.distance.textContent=Math.floor(distance);ui.reflection.textContent=count?messages[Math.min(count-1,10)]:'11 LIGHTS · ONE FOR EACH STEP TOWARD REMEMBRANCE'}function tone(freq=520){if(!audio)return;ac??=new AudioContext();const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.028,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.35);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+.35)}function rise(){if(state==='ready'||state==='complete')start();if(state!=='playing')return;plane.vy=-Math.max(220,H*.4)}function start(){reset();state='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}function complete(){state='complete';ui.kicker.textContent='SEPTEMBER 11, 2001';ui.title.innerHTML='Never<br><em>forget.</em>';ui.message.innerHTML='In memory of those lost.<br>In honor of those who ran toward danger.<br>May remembrance lead us toward compassion.';ui.start.textContent='REMEMBER AGAIN →';ui.overlay.classList.remove('hidden');tone(392)}
function update(dt){t+=dt;distance+=dt*10;plane.vy+=Math.max(520,H*.88)*dt;plane.y+=plane.vy*dt;plane.rot=Math.max(-.28,Math.min(.42,plane.vy/600));if(plane.y<70){plane.y=70;plane.vy=45}if(plane.y>H-155){plane.y=H-155;plane.vy=-150}for(const light of lights){light.x-=85*dt;if(!light.taken&&Math.hypot(light.x-plane.x,light.y-plane.y)<32){light.taken=true;count++;ui.announcement.textContent=messages[count-1];for(let i=0;i<18;i++)particles.push({x:light.x,y:light.y,vx:(Math.random()-.5)*100,vy:(Math.random()-.5)*100,a:1});tone(440+count*22);sync();if(count===11)return complete()}}lights=lights.filter(l=>l.x>-50&&!l.taken);if(lights.length<4&&count+lights.length<11)spawn(W+100);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.a-=dt*.9}particles=particles.filter(p=>p.a>0)}
function cloud(x,y,s=1){ctx.fillStyle='#dce9f2aa';ctx.beginPath();ctx.arc(x,y,18*s,0,7);ctx.arc(x+22*s,y-8*s,25*s,0,7);ctx.arc(x+49*s,y,19*s,0,7);ctx.fill()}function skyline(){const base=H-55;ctx.fillStyle='#17283c';for(let x=0;x<W;x+=18){const ht=14+(x*7%42);ctx.fillRect(x,base-ht,15,ht)}const tw=W*.64;ctx.fillStyle='#20354a';ctx.fillRect(tw,base-137,31,137);ctx.fillRect(tw+38,base-128,31,128);ctx.fillStyle='#314b64';for(const ox of[tw,tw+38])for(let y=base-120;y<base-10;y+=10)ctx.fillRect(ox+5,y,21,2);ctx.fillStyle='#e6d59a55';ctx.fillRect(tw+13,base-205,4,68);ctx.fillRect(tw+51,base-198,4,70)}function drawLight(l){const pulse=1+Math.sin(t*3+l.pulse)*.12;ctx.save();ctx.translate(l.x,l.y);ctx.strokeStyle='#f7dfa0';ctx.lineWidth=2;ctx.shadowBlur=18;ctx.shadowColor='#ffe9a8';ctx.beginPath();ctx.arc(0,0,16*pulse,0,7);ctx.stroke();ctx.fillStyle='#fff4c8';ctx.beginPath();ctx.arc(0,0,4,0,7);ctx.fill();ctx.restore()}
function draw(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#477ca4');g.addColorStop(.62,'#9ebfd0');g.addColorStop(1,'#e7c99b');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);cloud(W-(t*12%(W+100))-80,115,.55);cloud(W-(t*7%(W+180))+20,245,.4);for(const l of lights)drawLight(l);skyline();for(const p of particles){ctx.globalAlpha=p.a;ctx.fillStyle='#fff0b2';ctx.beginPath();ctx.arc(p.x,p.y,3,0,7);ctx.fill()}ctx.globalAlpha=1;ctx.save();ctx.translate(plane.x,plane.y);ctx.rotate(plane.rot);ctx.fillStyle='#edf2f4';ctx.beginPath();ctx.moveTo(31,0);ctx.lineTo(-20,-11);ctx.lineTo(-34,-5);ctx.lineTo(-18,2);ctx.lineTo(-8,18);ctx.lineTo(4,18);ctx.lineTo(1,3);ctx.closePath();ctx.fill();ctx.fillStyle='#415f79';ctx.fillRect(-24,-10,8,11);ctx.fillStyle='#223a50';ctx.fillRect(12,-3,7,5);ctx.strokeStyle='#789bb6';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-7,4);ctx.lineTo(14,10);ctx.stroke();ctx.restore()}
function loop(now){if(state!=='playing')return;const dt=Math.min(.03,(now-last)/1000);last=now;update(dt);draw();if(state==='playing')requestAnimationFrame(loop)}canvas.addEventListener('pointerdown',e=>{e.preventDefault();rise()});ui.start.onclick=()=>state==='paused'?(state='playing',ui.overlay.classList.add('hidden'),last=performance.now(),requestAnimationFrame(loop)):start();document.querySelector('#restart').onclick=start;ui.sound.onclick=()=>{audio=!audio;ui.sound.textContent=audio?'SOUND ON':'SOUND OFF'};addEventListener('keydown',e=>{if([' ','ArrowUp'].includes(e.key)){e.preventDefault();rise()}if(e.key.toLowerCase()==='p'&&state==='playing'){state='paused';ui.kicker.textContent='FLIGHT PAUSED';ui.title.textContent='A quiet pause.';ui.message.textContent='Resume whenever you are ready.';ui.start.textContent='CONTINUE →';ui.overlay.classList.remove('hidden')}});addEventListener('resize',()=>{resize();if(state!=='playing'){reset();draw()}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing'){state='paused';ui.overlay.classList.remove('hidden')}});resize();reset();draw();
